import json
from ledger import REGIONS
def report(encoded):
    totals = dict.fromkeys(REGIONS, 0)
    for row in json.loads(encoded):
        totals[row['region']] += row['cents']
    return ''.join(f'{region}:{totals[region]}\n' for region in REGIONS)

