import json, statistics, time
from parsers import INPUT, EXPECTED, a, b
samples = []
for _ in range(5):
    for name, fn in (('A', a), ('B', b)):
        completed = errors = 0
        start = time.perf_counter()
        for text, expected in zip(INPUT, EXPECTED):
            try:
                result = fn(text)
            except ValueError:
                errors += 1
            else:
                assert abs(result - expected) < 1e-9
                completed += 1
        elapsed = time.perf_counter() - start
        samples.append({'option': name, 'ms': elapsed * 1000, 'attempted': len(INPUT),
            'completed': completed, 'errors': errors, 'attempts_per_second': len(INPUT) / elapsed})
print(json.dumps({'conditions': 'same preloaded valid inputs, same interpreter, concurrency 1', 'samples': samples,
    'median_ms': {name: statistics.median(s['ms'] for s in samples if s['option'] == name) for name in ('A', 'B')}}))

